import sys
from pysat.solvers import RC2
from pysat.formula import WCNF
from itertools import combinations

n = 14
wcnf = WCNF()

# Variables for edges
def edge_var(u, v):
    if u > v:
        u, v = v, u
    return u * n + v + 1

# No cycles of length 3
for c in combinations(range(n), 3):
    wcnf.append([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

# No cycles of length 4
for c in combinations(range(n), 4):
    # 3 possible 4-cycles on 4 vertices
    wcnf.append([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[2], c[3]), -edge_var(c[0], c[3])])
    wcnf.append([-edge_var(c[0], c[1]), -edge_var(c[1], c[3]), -edge_var(c[3], c[2]), -edge_var(c[0], c[2])])
    wcnf.append([-edge_var(c[0], c[2]), -edge_var(c[2], c[1]), -edge_var(c[1], c[3]), -edge_var(c[0], c[3])])

# No cycles of length 5
import itertools
for c in combinations(range(n), 5):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[4] and p[1] < p[4]:
            wcnf.append([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[0])])

# No cycles of length 6
for c in combinations(range(n), 6):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[5] and p[1] < p[5]:
            wcnf.append([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[5]), -edge_var(p[5], p[0])])

# Soft clauses to maximize edges
for u in range(n):
    for v in range(u + 1, n):
        wcnf.append([edge_var(u, v)], weight=1)

print("Solving...")
with RC2(wcnf) as rc2:
    model = rc2.compute()
    if model:
        edges = []
        for u in range(n):
            for v in range(u + 1, n):
                if model[edge_var(u, v) - 1] > 0:
                    edges.append((u, v))
        print(f"Max edges: {len(edges)}")
        print(edges)
    else:
        print("UNSAT")

